#include <iostream>
using namespace std;

template <typename T>
struct Tag {
    static const char* name() { return "普通料"; }
};

template <typename T>
struct Tag<T*> {
    static const char* name() { return "指向牌"; }
};

int main() {
    cout << Tag<int*>::name() << endl;
    cout << Tag<{t}*>::name() << endl;
    return 0;
}
